import"./main-B-S92MT7.js";document.addEventListener("DOMContentLoaded",()=>{const l=document.getElementById("min-money"),s=document.getElementById("max-money"),m=document.getElementById("probability"),c=document.getElementById("randomize-btn"),d=document.getElementById("result-card"),u=document.getElementById("result-amount");function g(){const e=parseFloat(l.value),n=parseFloat(s.value),o=parseFloat(m.value)/100;if(isNaN(e)||isNaN(n)||isNaN(o)||e<0||n<0||e>n){Swal.fire({icon:"error",title:"Invalid Input",text:"Please ensure Min is less than Max, and all inputs are valid numbers.",confirmButtonColor:"#ef4444"});return}const p=n-e,a=e+p*(1-.3),i=a;let t;Math.random()<o?(t=Math.random()*(n-i)+i,console.log("Picking from HIGH range: "+t)):(t=Math.random()*(a-e)+e,console.log("Picking from LOW range: "+t));const r=t.toFixed(2);u.textContent=`₱${r}`,d.classList.remove("hidden"),Swal.fire({title:"🎉 Aguinaldo Generated!",text:`You are giving ₱${r}!`,icon:"success",confirmButtonText:"Woohoo!",confirmButtonColor:"#10b981"})}c.addEventListener("click",g),window.applyTheme&&window.applyTheme()});
